from sklearn.linear_model import Lasso,HuberRegressor,Ridge,LinearRegression
from catboost import CatBoostRegressor
D=pd.read_csv('/work/alloy_pair_target_train.csv'); y=D.pop('target').values; cats=['heat_treatment','route']; nums=[c for c in D if c not in cats]; nonfe=[c for c in nums if c!='Fe']
s0=StandardScaler().fit(D[nums]); z0=s0.transform(D[nums]); poly=PolynomialFeatures(2,include_bias=False).fit(z0); z=poly.transform(z0); ohe=OneHotEncoder(sparse_output=False,handle_unknown='ignore').fit(D[cats]); c=ohe.transform(D[cats]); X0=np.c_[z,c]; sx=StandardScaler().fit(X0); X=sx.transform(X0)
models={}
for a in [1,2]:models['lasso'+str(a)]=Lasso(alpha=a,max_iter=100000).fit(X,y)
for a in [1]:models['ridge'+str(a)]=Ridge(alpha=a).fit(X,y)
names=poly.get_feature_names_out(nums); aid=[i for i,n in enumerate(names) if ' ' not in n]; A0=np.c_[z[:,aid],c]; sa=StandardScaler().fit(A0); A=sa.transform(A0)
models['huber']=HuberRegressor(epsilon=1.75,alpha=.1,max_iter=10000).fit(A,y); models['addOLS']=LinearRegression().fit(A,y)
cb=CatBoostRegressor(iterations=800,depth=4,learning_rate=.04,loss_function='RMSE',verbose=False,random_seed=1,l2_leaf_reg=5).fit(D,y,cat_features=cats)

def arrays(x,ht,route):
 raw=np.empty(len(nums)); j=0
 for i,n in enumerate(nums):
  if n=='Fe': raw[i]=100-sum(x[:12])
  else: raw[i]=x[j];j+=1
 zz=poly.transform(((raw-s0.mean_)/s0.scale_).reshape(1,-1)); cc=ohe.transform(np.array([[ht,route]],dtype=object)); full=(np.c_[zz,cc]-sx.mean_)/sx.scale_; add=(np.c_[zz[:,aid],cc]-sa.mean_)/sa.scale_; return raw,full,add

def onepred(x,ht,route,n):
 _,f,a=arrays(x,ht,route);return models[n].predict(a if n in ['huber','addOLS'] else f)[0]
def allpred(x,ht,route):
 raw,f,a=arrays(x,ht,route); out={n:float(m.predict(a if n in ['huber','addOLS'] else f)[0]) for n,m in models.items()}
 row=pd.DataFrame([dict(zip(nums,raw))|{'heat_treatment':ht,'route':route}]);out['cat']=float(cb.predict(row)[0]);return out
