 for ht in hvals:
  for route in rvals:
   res=differential_evolution(lambda x:-onepred(x,ht,route,modelname),bounds,seed=3,popsize=6,maxiter=100,tol=1e-7,polish=True)
   if best is None or res.fun<best[0]:best=(res.fun,res.x,ht,route)
 _,x,ht,route=best
 print('\nMAX',modelname,'cats',ht,route)
 print('x',','.join(f'{v:.4f}' for v in x),'sum',sum(x[:12]))
 print(allpred(x,ht,route))
# lasso selected
m=models['lasso2']; ix=np.flatnonzero(m.coef_); allnames=list(poly.get_feature_names_out(nums))+list(ohe.get_feature_names_out(cats))
print('\nlasso2 terms',len(ix))
for i in ix[np.argsort(abs(m.coef_[ix]))[::-1]]:print(f'{allnames[i]:40} {m.coef_[i]:8.3f}')
