 zz=((raw-s0.mean_)/s0.scale_).reshape(1,-1);cc=o.transform([[ht,rt]]);f=sf.transform(np.c_[poly.transform(zz),cc]);aa=sa.transform(np.c_[zz,zz**2,cc]);return f,aa
def pp(x,ht,rt,a):
 f,aa=ar(x,ht,rt);return ridges[a].predict(f)[0],hub.predict(aa)[0]
