   x=sl.x; pr,ph=pp(x,ht,rt,alpha)
   if abs(pr-1051)<.1 and (best is None or ph>best[0]):best=(ph,pr,x,ht,rt,sl.success)
 print('\nalpha',alpha,'best',None if best is None else best[:2]+best[3:])
 if best:
  ph,pr,x,ht,rt,succ=best;print(','.join(f'{v:.6f}' for v in x),'sum',sum(x[:12]),'cats',ht,rt,'success',succ)
  print('all ridge', {a:pp(x,ht,rt,a)[0] for a in ridges},'huber',ph)
